export function MenuList({ children }) {
  return (
    <ul
      role="menu"
      className="flex flex-col gap-1 p-2 rounded-lg border border-zinc-800 bg-zinc-900"
    >
      {children}
    </ul>
  );
}

export function MenuItem({ children, active = false }) {
  return (
    <li role="none">
      <button
        type="button"
        role="menuitem"
        className={`w-full flex items-center gap-2 px-3 py-2 rounded-lg text-sm transition-colors ${
          active
            ? "bg-zinc-800 text-zinc-100"
            : "text-zinc-200 hover:bg-zinc-800"
        }`}
      >
        {children}
      </button>
    </li>
  );
}
